}

{
  "type": "object",
  "properties": {
    "query": {
      "type": "string",
      "description": "The phrase to search for (keyword, or a regular expression with regex: true). Required in search mode."
    },
    "scope": {
      "type": "string",
      "enum": [
        "branch",
        "tree"
      ],
      "description": "branch (default) searches the active branch only; tree spans forks and abandoned branches too."
    },
    "mode": {
      "type": "string",
      "enum": [
        "search",
        "map"
      ],
      "description": "search (default) finds records; map reports the archive structure (counts, hidden totals, checkpoint tree)."
    },
    "kinds": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Only these record types (message, compaction, compact_checkpoint, custom, …). Empty keeps every kind."
    },
    "before": {
      "type": "string",
      "description": "Only records older than this ISO-8601 instant."
    },
    "after": {
      "type": "string",
      "description": "Only records newer than this ISO-8601 instant."
    },
    "regex": {
      "type": "boolean",
      "description": "Match query as a case-insensitive regular expression (default: literal keyword)."
    },
    "maxHits": {
      "type": "integer",
      "description": "Cap on returned pointers (default 40, max 200). A capped scan returns a continuation token."
    },
    "continuation": {
      "type": "integer",
      "description": "The token a previous capped call returned — resumes the scan after the records already examined."
    }
  }
}

content.text:
/// Per-call foreground liveness reminders (gh-1055): the headless/line-mode
/// console presentation for a tool call that runs long — the analog of the
/// TUI's visible-waiting row, which line mode cannot repaint.
///
/// While a foreground tool call is in flight, the tracker (one instance per
/// CLI host) evaluates on a ~60s chain: past `waiting.toolLivenessSeconds`
/// every tick prints ONE grep-friendly status line (elapsed seconds, tool
/// name, short command tail, and the #1349 background hint); past
/// `waiting.toolEscalateSeconds` the tick instead prints — exactly once per
/// stuck call — the fuller background escape-hatch hint, so an operator
/// tailing the run (and the model reading its own logs) learns the call is
/// a `bash background: true` / `/tasks` / `--wait-for-jobs` candidate.
///
/// One clock only: every elapsed value derives from the host's
/// waiting-clock seam (the same `waitingClock` the #450 waiting layer and
/// the future #1054 stuck-call heartbeat records use — no second clock).
///
/// The class itself is transport-free; the host (CLI) wires the print sink
/// through [ToolLivenessTracker.onRemind]/[onEscalate].
library;

import 'dart:async';

import 'tui_theme.dart';

/// Default threshold before per-call liveness reminders start (`waiting:
/// toolLivenessSeconds`; `0` disables the reminders).
const defaultToolLivenessSeconds = 60;

/// Default reminder cadence in seconds (`waiting: toolLivenessTickSeconds`;
/// `0` disables the production timer chain — the tick seam still evaluates).
const defaultToolLivenessTickSeconds = 60;

/// Default threshold for the one-time background escape-hatch hint
/// (`waiting: toolEscalateSeconds`; `0` disables the hint).
const defaultToolEscalateSeconds = 300;

/// The background escape hatch an escalation line names (gh-1055): the
/// tool flag, the job board, the headless wait flag, and — AC6 — the
/// cancellation affordance per case: a backgrounded call stops via its
/// job id (`fa bash_job stop <id>`); the foreground call this tracker
/// watches has only Ctrl+C (the SIGINT parity exit) / inbox steering,
/// which land only once the call unwinds (until #1053 bounds the shell).
const String toolLivenessEscalationHint =
    'background candidate: bash background: true, job board /tasks, '
    '--wait-for-jobs · cancel: fa bash_job stop <id> once backgrounded; '
    'Ctrl+C / inbox steering takes effect once the call unwinds '
    '(until #1053)';

/// The short background hint every periodic reminder line carries
/// (issue #1349): a warned parked turn is still a parked turn, so each
/// reminder names the escape while the call keeps running — the model
/// reading its own logs sees the option before the 300s escalation.
const String toolLivenessForegroundHint =
    'consider background: true for long waits (settle notification wakes you)';

/// Flatten + clip budget for the command tail inside a liveness line — the
/// line must stay grep-friendly and single-line (repeated every tick).
const int toolLivenessDetailClip = 96;

/// Per-turn cap on #1185 stuck-call nudges (E2, the TTSR
/// `maxInjectionsPerTurn` analog): a turn whose calls keep hanging gets
/// at most this many model-facing nudges, refilled at each real turn
/// start — auto-continue turns deliberately do not refill (the reset
/// sits after the `_beginUserPrompt` auto-continue early-return, so a
/// degenerate empty-reply loop cannot farm fresh nudges). Per-call dedup
/// already bounds one call to one nudge, so breaching the cap takes many
/// DISTINCT stuck calls, and a model that ignores them burns the cap
/// honestly instead of drowning its context.
const int maxToolNudgesPerTurn = 3;

/// The #1185 model-facing nudge's sender anchor — the grep-friendly
/// attribution prefix of every injected notice (`[liveness watchdog] …`).
/// Exported because it is a delivery contract: operators and tests grep
/// for it, so lib and tests must share one literal.
const String toolNudgeAnchor = '[liveness watchdog]';

/// The #1185 model-facing nudge (the steering injection an escalation
/// fires): same facts as the console escalation line, addressed to the
/// MODEL through the steering channel (the agent's follow-up queue —
/// boundary delivery without the soft-yield signal) — decide: keep
/// waiting, background the work, or kill the job. The harness takes no
/// action itself (auto-kill stays a non-goal); the notice is a
/// `<system-notice>` user message, the same shape the background-job
/// settle notice uses.
String toolNudgeNotice(ToolLivenessCall call, DateTime now) {
  final seconds = now.difference(call.startedAt).inSeconds;
  return '<system-notice>\n'
      '$toolNudgeAnchor Foreground tool call `${call.toolName}` '
      '("${clipToolLivenessDetail(call.detail)}") has been running '
      '${seconds}s with no output. Decide and act on your next turn: keep '
      'waiting (continue as-is), background the work (`bash background: '
      'true` for a new command; a call already moved to the background is '
      'a job — manage it with bash_job action: output | status | stop), or '
      'kill the job. This notice does not stop the call.\n'
      '</system-notice>';
}

/// One watched foreground tool call. The tracker owns the instances; the
/// escalated flag flips when the hint fired for THIS call.
final class ToolLivenessCall {
  ToolLivenessCall({
    required this.id,
    required this.toolName,
    required this.detail,
    required this.startedAt,
  });

  /// The tool call id (`ToolCall.id`).
  final String id;

  /// The tool's name (`bash`, `read`, …).
  final String toolName;

  /// The short human detail (the command tail, path, question) — the same
  /// string the tool row showed at start.
  final String detail;

  /// When the call started — read from the tracker's clock (the host's
  /// waiting-clock seam; gh-1055 AC5: one clock for every elapsed value).
  final DateTime startedAt;

  /// Whether the background hint already fired for this call (AC3: exactly
  /// once per stuck call).
  bool escalated = false;
}

/// Watches in-flight foreground tool calls and fires the liveness lines.
///
/// One-shot timer chain, not [Timer.periodic] — the cadence getter is read
/// every leg so a config change applies at the next tick, and the chain
/// disarms the moment the last call ends. Transport-free.
final class ToolLivenessTracker {
  ToolLivenessTracker({
    required this._onRemind,
    required this._onEscalate,
    int Function()? livenessSeconds,
    int Function()? tickSeconds,
    int Function()? escalateSeconds,
    DateTime Function()? clock,
  }) : _livenessSeconds = livenessSeconds ?? (() => defaultToolLivenessSeconds),
       _tickSeconds = tickSeconds ?? (() => defaultToolLivenessTickSeconds),
       _escalateSeconds = escalateSeconds ?? (() => defaultToolEscalateSeconds),
       _clock = clock ?? DateTime.now;

  final void Function(ToolLivenessCall call) _onRemind;
  final void Function(ToolLivenessCall call) _onEscalate;
  final int Function() _livenessSeconds;
  final int Function() _tickSeconds;
  final int Function() _escalateSeconds;
  final DateTime Function() _clock;

  /// In-flight calls by tool-call id; insertion order = call start order.
  final _calls = <String, ToolLivenessCall>{};

  Timer? _timer;

  /// The watched calls, oldest first.
  List<ToolLivenessCall> get inFlight => [..._calls.values];

  /// A foreground tool call started: begin watching it. The chain arms
  /// only when idle — a call starting mid-leg waits for the running leg
  /// (the aggregate tick covers every in-flight call anyway).
  void callStarted(String id, String toolName, String detail) {
    _calls[id] = ToolLivenessCall(
      id: id,
      toolName: toolName,
      detail: detail,
      startedAt: _clock(),
    );
    if (_timer == null) _arm();
  }

  /// The call finished: the watch (and the escalated state) goes with it —
  /// a NEW stuck call escalates afresh.
  void callEnded(String id) {
    _calls.remove(id);
    if (_calls.isEmpty) stop();
  }

  /// Disarms the chain (last call ended, or the host is shutting down).
  void stop() {
    _timer?.cancel();
    _timer = null;
  }

  /// One evaluation now: for every in-flight call, fire lines by elapsed —
  /// the one-time escalation hint past the escalation threshold (that tick
  /// the hint IS the liveness line), otherwise the periodic reminder past
  /// the liveness threshold (continues after the hint fired, and after it).
  /// `toolLivenessSeconds: 0` is the feature kill switch; a disabled
  /// escalation (`toolEscalateSeconds: 0`) keeps the reminders.
  ///
  /// Mirrors the sibling `WaitingHeartbeat.tick` (issue #450): the pending
  /// leg is cancelled first and the chain re-arms a full cadence from
  /// NOW — so the manual seam is observable (it owns the chain state) and
  /// can never double-fire with the production leg. The production timer
  /// legs land here; tests call it directly.
  void tick() {
    _timer?.cancel();
    _timer = null;
    _evaluate();
    if (_calls.isNotEmpty) _arm();
  }

  void _evaluate() {
    if (_calls.isEmpty) return;
    final remindAfter = _livenessSeconds();
    if (remindAfter <= 0) return;
    final escalateAfter = _escalateSeconds();
    final now = _clock();
    for (final call in inFlight) {
      final elapsed = now.difference(call.startedAt).inSeconds;
      if (elapsed < remindAfter) continue;
      if (escalateAfter > 0 && elapsed >= escalateAfter) {
        if (call.escalated) {
          _onRemind(call);
          continue;
        }
        call.escalated = true;
        _onEscalate(call);
        continue;
      }
      _onRemind(call);
    }
  }

  void _arm() {
    if (_calls.isEmpty) return;
    final seconds = _tickSeconds();
    if (seconds <= 0) return;
    _timer = Timer(Duration(seconds: seconds), () {
      _timer = null;
      tick();
    });
  }
}

/// The periodic reminder line (gh-1055 AC1): a pending glyph + the tool
/// tag + the command tail, e.g. `○ [bash] sleep 500 — running 120s ·
/// consider background: true …` (gh-1446 AC8: the glyph resolves through
/// the symbol table, no hardcoded `⏳`). Single line, tool name, short
/// command tail, elapsed seconds, and the #1349 background hint.
String toolLivenessReminderLine(ToolLivenessCall call, DateTime now) =>
    _livenessLine(call, now, hint: toolLivenessForegroundHint);

/// The escalation line (gh-1055 AC3): the reminder's facts plus the
/// background escape hatch. Emitted once per stuck call.
String toolLivenessEscalationLine(ToolLivenessCall call, DateTime now) =>
    _livenessLine(call, now, hint: toolLivenessEscalationHint);

String _livenessLine(ToolLivenessCall call, DateTime now, {String? hint}) {
  final elapsed = now.difference(call.startedAt).inSeconds;
  final detail = clipToolLivenessDetail(call.detail);
  final pending = FaThemeController.instance.sym('status.pending');
  final head = detail.isEmpty
      ? '$pending [${call.toolName}] running ${elapsed}s'
      : '$pending [${call.toolName}] $detail — running ${elapsed}s';
  return hint == null ? head : '$head · $hint';
}

/// Guarantees the single-line rule: whitespace runs collapse (a heredoc or
/// multi-line command never spans lines), and an overlong tail clips with
/// an ellipsis — the full command lives in the tool row above.
String clipToolLivenessDetail(String detail) {
  final flat = detail.replaceAll(RegExp(r'\s+'), ' ').trim();
  if (flat.length <= toolLivenessDetailClip) return flat;
  return '${flat.substring(0, toolLivenessDetailClip)}…';
}

/// The `bash` tool ([shellTool], a ported subset of pi's `tools/bash.ts`) and the `bash_job` tool ([bashJobTool]): foreground runs with transient-failure retries, the yield-aware job path, password-prompt detection wiring, and background-job status/output/stop actions. Split out of `builtin_tools.dart` to keep that file under the repo line gate; same library (a `part of`), so the privates stay visible.
part of 'builtin_tools.dart';

// ---------------------------------------------------------------------------
// bash (ported subset of pi's tools/bash.ts)
// ---------------------------------------------------------------------------

Duration _resolveTimeout(num timeoutSeconds) {
  if (!timeoutSeconds.isFinite || timeoutSeconds <= 0) {
    throw StateError('Invalid timeout: must be a finite number of seconds');
  }
  final timeoutMs = (timeoutSeconds * 1000).round();
  if (timeoutMs > _maxTimeoutMs) {
    throw StateError(
      'Invalid timeout: maximum is ${_maxTimeoutMs / 1000} seconds',
    );
  }
  return Duration(milliseconds: timeoutMs);
}

String _appendStatus(String text, String status) {
  return text.isEmpty ? status : '$text\n\n$status';
}

/// Extracts the effective timeout in whole seconds from a shell timeout
/// error message (`timeout: 0:00:30` — the shape both LocalShell and the
/// WASI sandbox emit), or null when no parseable duration is present.
/// Sub-second caps round up to 1 so the text never claims "after 0s".
int? timeoutSecondsFromMessage(String message) {
  final match = RegExp(
    r'timeout:\s*(\d+):(\d{1,2}):(\d{1,2})',
  ).firstMatch(message);
  if (match == null) return null;
  final seconds =
      int.parse(match.group(1)!) * 3600 +
      int.parse(match.group(2)!) * 60 +
      int.parse(match.group(3)!);
  return seconds > 0 ? seconds : 1;
}

/// The honest timeout status line (gh-1444 AC5): the model's own cap when
/// it passed one, else the shell's effective cap — the job's recorded exec
/// timeout, or the duration parsed from the exec error's
/// `timeout: <duration>` message — never "unknown seconds". When no cap is
/// recoverable at all the line states the timeout without inventing a
/// number.
String bashTimeoutStatus({
  num? timeoutArg,
  Duration? effectiveTimeout,
  String? errorMessage,
}) {
  if (timeoutArg != null) {
    return 'Command timed out after ${_formatTimeoutSeconds(timeoutArg)} '
        'seconds';
  }
  final seconds = effectiveTimeout?.inSeconds;
  if (seconds != null && seconds > 0) {
    return 'Command timed out after $seconds seconds';
  }
  final parsed = errorMessage == null
      ? null
      : timeoutSecondsFromMessage(errorMessage);
  if (parsed != null) {
    return 'Command timed out after $parsed seconds';
  }
  return 'Command timed out';
}

/// Renders a timeout argument the way the model passed it (whole numbers
/// stay whole, fractions keep their digits).
String _formatTimeoutSeconds(num seconds) {
  if (seconds == seconds.truncate()) {
    return '${seconds.truncate()}';
  }
  return '$seconds';
}

/// Foreground sleep deny threshold (issue #1349): a bare `sleep` longer
/// than this is rejected at call validation. A bare long sleep is never
/// legitimate foreground work — it parks the whole turn (steering and the
/// cancel path cannot reach the agent while the call stays open) — while
/// real long work (builds, test suites) keeps its foreground path.
const int maxForegroundSleepSeconds = 60;

/// One `sleep` duration argument: a plain number or a GNU-suffixed one
/// (`30`, `1.5s`, `2m`, `1h`, `7d`, case-insensitive).
final RegExp _sleepDurationArg = RegExp(
  r'^(\d+(?:\.\d+)?)([smhd]?)$',
  caseSensitive: false,
);

/// The total requested duration in seconds iff [command] is a BARE
/// `sleep <duration>…` (nothing but sleep and its duration arguments),
/// else null. Deliberately conservative (issue #1349): sleeps wrapped in
/// shell constructs are phase 2 — extend detection only if the deny data
/// shows the class survives.
///
/// Known false negatives — intentional phase-1 bypasses, recorded where
/// the deny data is collected (phase 2 candidates, dmtools-agents#767):
/// quoted durations (`sleep "300"`), env prefixes (`FOO=1 sleep 300`),
/// case variants (`SLEEP 300`), and trailing separators (`sleep 300;`).
double? bareForegroundSleepSeconds(String command) {
  final words = command.trim().split(RegExp(r'\s+'));
  if (words.first != 'sleep' || words.length < 2) return null;
  var total = 0.0;
  for (final word in words.skip(1)) {
    final match = _sleepDurationArg.firstMatch(word);
    if (match == null) return null;
    final value = double.parse(match.group(1)!);
    total += switch (match.group(2)!.toLowerCase()) {
      'm' => value * 60,
      'h' => value * 3600,
      'd' => value * 86400,
      _ => value, // '' | 's'
    };
  }
  return total;
}

/// The instructive validation denial for a bare long foreground `sleep`,
/// or null when the command may run in the foreground. The caller gates on
/// `timeout == null` (an explicit timeout is a deliberate bail cap — the
/// call unwinds there, steering and cancel included) and passes [canJob]
/// so the escape advice matches what the environment actually offers —
/// background advice would dead-end in a no-jobs host.
String? foregroundSleepDenial(String command, {required bool canJob}) {
  final seconds = bareForegroundSleepSeconds(command);
  if (seconds == null || seconds <= maxForegroundSleepSeconds) return null;
  final label = seconds == seconds.truncateToDouble()
      ? '${seconds.truncate()}'
      : '$seconds';
  final escape = canJob
      ? 'Re-run it with background: true: the command keeps running as a '
            'job, the job id returns immediately, and a settle notification '
            'wakes you when it finishes; collect progress with bash_job '
            '(action: output).'
      : 'Background jobs are not supported in this environment; bound the '
            'wait with an explicit timeout (seconds) instead — the call '
            'unwinds at the cap, so steering and cancel can reach you.';
  return 'Denied: a bare foreground sleep of ${label}s parks the whole '
      'turn — owner steering and cancel cannot reach the agent while the '
      'call stays open. $escape Never poll in the foreground.';
}

/// Creates the `bash` tool: executes a shell command via [ExecutionEnv.exec]
/// and returns stdout followed by stderr, truncated to the last
/// [defaultToolMaxLines] lines / [defaultToolMaxBytes] bytes. A non-zero
/// exit code, timeout, or abort throws (the loop turns it into an error
/// tool result, pi semantics).
///
/// With [jobs] (and an environment implementing [BackgroundShell]) the tool
/// gains two background behaviors:
///
/// - `background: true` starts the command detached and returns immediately
///   with the job id; completion is reported back as a follow-up message.
/// - Foreground runs still block, but a user steering message mid-run
///   (the loop's soft-yield token, see [currentYieldToken]) moves the command
///   into a background job WITHOUT killing it: the tool call answers with the
///   job id and a partial-output tail, and the user message is delivered at
///   the next step boundary.
AgentTool shellTool(
  ExecutionEnv env, {
  ShellJobRegistry? jobs,
  Duration retryBackoff = _bashRetryBackoff,
  PasswordPromptCallback? onPasswordPrompt,
  Duration passwordQuiet = _bashPasswordQuiet,

  /// The host's resolved redaction config for the shape interceptor
  /// (issue #1408 AC3, review 5456649624): the same `redact:` section
  /// steers command rewriting and result/job-log masking. Null = the
  /// default config (vendor shapes on) for direct tool users; the CLI
  /// passes its boot-resolved config (disabled when redaction is off).
  RedactionConfig? redactionConfig,

  /// Live snapshot of the values the host registered as secrets
  /// (`request_secret`, preconfig keys): those literals are EXEMPT from
  /// command rewriting so an approved value still materializes while the
  /// pipeline masks it in transcripts (review 5456649624).
  Set<String> Function()? approvedSecretLiterals,
}) {
  return AgentTool(
    name: bashToolName,
    label: 'bash',
    tier: ApprovalTier.exec,
    description:
        'Execute a bash command in the current working directory. Returns '
        'stdout and stderr. Output is truncated to the last '
        '$defaultToolMaxLines lines or ${defaultToolMaxBytes ~/ 1024}KB '
        '(whichever is hit first). Optionally provide a timeout in seconds. '
        'Timeouts you set are retried automatically '
        '(${bashToolMaxRetries + 1} attempts total); retries appear as '
        '[bash attempt N]. Environment-default timeouts fail once with the '
        'partial output. '
        'For long-running commands (builds, servers, watchers) pass '
        'background: true — the command keeps running as a job, you get its '
        'id immediately and are notified when it finishes; check progress '
        'with bash_job. A foreground command that is still running when the '
        'user sends a message is moved to a background job untouched (never '
        'killed) so the user gets an answer right away.',
    parameters: const {
      'type': 'object',
      'properties': {
        'command': {
          'type': 'string',
          'description': 'The bash command to execute',
        },
        'timeout': {
          'type': 'number',
          'description': 'Timeout in seconds (optional, no default timeout)',
        },
        'background': {
          'type': 'boolean',
          'description':
              'Run detached and return the job id immediately (optional, '
              'default false). Use for long-running commands.',
        },
        'stdin': {
          'type': 'string',
          'description':
              'Optional text written to the command\'s stdin right after '
              'start (a password/passphrase the USER supplied via the ask '
              'tool, or "y\\n"). Use when the command prompts for input, '
              'e.g. ssh-add or sudo. Never invent secrets — ask first.',
        },
      },
      'required': ['command'],
    },
    execute: (arguments, cancelToken, onUpdate) async {
      cancelToken?.throwIfCancelled();
      final command = arguments['command'] as String;
      // Issue #1408 AC3: the shape interceptor rewrites recognized secret
      // SHAPES (and only those — key-like-but-unmatched text, e.g. a
      // filename the agent is creating, stays byte-identical) and the
      // result notice names every rewrite so the agent sees what changed
      // instead of discovering corruption by I/O error.
      final rewrite = redactBashCommandSecretShapes(
        command,
        config: redactionConfig ?? const RedactionConfig(),
        approvedLiterals: approvedSecretLiterals?.call() ?? const {},
      );
      final effectiveCommand = rewrite?.command ?? command;
      final rewriteNotice = rewrite?.notice;
      final timeoutArg = arguments['timeout'] as num?;
      final timeout = timeoutArg == null ? null : _resolveTimeout(timeoutArg);
      final background = arguments['background'] as bool? ?? false;
      final stdinData = arguments['stdin'] as String?;
      final canJob = jobs != null && jobs.isSupported;

      // Issue #1349: a bare long foreground sleep is rejected at call
      // validation — it parks the turn; background: true is the fix. An
      // explicit `timeout` is a deliberate bail cap (the call unwinds at
      // the cap, so steering and cancel reach the agent), not a park.
      if (!background && timeout == null) {
        final sleepDenial = foregroundSleepDenial(command, canJob: canJob);
        if (sleepDenial != null) return ToolExecutionResult.text(sleepDenial);
      }

      if (background) {
        if (!canJob) {
          return ToolExecutionResult.text(
            'Background execution is not supported in this environment — '
            'run the command in the foreground with an explicit timeout.',
          );
        }
        final entry = await jobs.start(
          effectiveCommand,
          options: ShellExecOptions(
            cwd: env.cwd,
            timeout: timeout,
            // gh-1455: no caller cancel token — a background job outlives
            // this call and is stopped through `bash_job stop` only; the
            // registry firewalls stray tokens too.
            stdinData: stdinData,
          ),
        );
        return ToolExecutionResult.text(
          '${rewriteNotice == null ? '' : '$rewriteNotice\n'}'
          'Started background job ${entry.id}.\n'
          'Log: ${entry.logPath}\n'
          'You will be notified when it finishes; check progress with '
          'bash_job (action: status | output | stop).',
        );
      }

      // Yield-aware foreground run: executed as a job from the start so a
      // steering message can move it to the background mid-flight without
      // killing the process. Settled before any yield → identical result to
      // the classic inline path.
      if (canJob && currentYieldToken() != null) {
        return _shellViaJob(
          env,
          jobs,
          effectiveCommand,
          stdinData: stdinData,
          timeout: timeout,
          timeoutArg: timeoutArg,
          cancelToken: cancelToken,
          yieldToken: currentYieldToken()!,
          onPasswordPrompt: onPasswordPrompt,
          passwordQuiet: passwordQuiet,
          rewriteNotice: rewriteNotice,
        );
      }

      return _runForegroundBash(
        env,
        effectiveCommand,
        timeout: timeout,
        timeoutArg: timeoutArg,
        cancelToken: cancelToken,
        stdinData: stdinData,
        retryBackoff: retryBackoff,
        rewriteNotice: rewriteNotice,
      );
    },
  );
}

/// The inline foreground bash run with transient-failure retry: a
/// timeout-class failure (the model's own cap, or an outer future cap on a
/// hung transport) is retried up to [bashToolMaxRetries] times — a hung
/// network call should be retried, not fail the turn (user report: a
/// stalled `gh` API call killed the whole run). Aborts and real command
/// failures (non-zero exit, exec errors) are never retried. Every retry
/// lands in the result as a `[bash attempt N]` notice so the model knows
/// earlier attempts hung or timed out.
Future<ToolExecutionResult> _runForegroundBash(
  ExecutionEnv env,
  String command, {
  required Duration? timeout,
  required num? timeoutArg,
  required CancelToken? cancelToken,
  required String? stdinData,
  required Duration retryBackoff,
  String? rewriteNotice,
}) async {
  final notices = <String>[?rewriteNotice];
  for (var attempt = 1; ; attempt++) {
    final canRetry = attempt <= bashToolMaxRetries;
    final Result<ShellExecResult, ExecutionError> result;
    try {
      result = await env.exec(
        command,
        options: ShellExecOptions(
          cwd: env.cwd,
          timeout: timeout,
          cancelToken: cancelToken,
          stdinData: stdinData,
        ),
      );
    } on TimeoutException {
      // An outer layer's future cap fired (transport hang); the exec
      // itself never answered.
      if (!canRetry) rethrow;
      notices.add(
        '[bash attempt $attempt/${bashToolMaxRetries + 1} hung — '
        'retrying]',
      );
      await Future<void>.delayed(retryBackoff);
      continue;
    }

    if (result.isErr) {
      final error = result.errorOrNull!;
      // gh-1444 C5: a timeout the MODEL passed is a transient-failure
      // candidate (a hung network call under a deliberate bail cap) and is
      // retried; a SHELL-default timeout (no timeout argument) is the
      // harness's own cap firing — re-running a long command up to 3×
      // parks the turn ("looked stuck"), so it fails once with the honest
      // text and the captured partial output.
      if (error.code == ExecutionErrorCode.timeout &&
          canRetry &&
          timeoutArg != null) {
        notices.add(
          '[bash attempt $attempt/${bashToolMaxRetries + 1} timed out'
          ' after ${timeoutArg}s — '
          'retrying]',
        );
        await Future<void>.delayed(retryBackoff);
        continue;
      }
      throw _bashFailureError(error, notices, timeoutArg);
    }

    final execResult = result.valueOrNull!;
    final rawOutput = _bashOutput(execResult);
    if (execResult.exitCode != 0) {
      throw StateError(
        _appendStatus(
          '${_retryNoticePrefix(notices)}${_truncateBashOutput(rawOutput)}',
          'Command exited with code ${execResult.exitCode}',
        ),
      );
    }
    final output = _truncateBashOutput(rawOutput);
    final text = output.isEmpty ? '(no output)' : output;
    return ToolExecutionResult.text('${_retryNoticePrefix(notices)}$text');
  }
}

/// The user-visible error for a non-retryable bash exec failure.
StateError _bashFailureError(
  ExecutionError error,
  List<String> notices,
  num? timeoutArg,
) {
  // gh-1053 (review rework): a killed call's error carries the captured
  // partial output — render it so the model sees WHERE the call stalled,
  // not just the verdict.
  return switch (error.code) {
    ExecutionErrorCode.aborted => StateError(
      _bashFailureWithCapture(error, _appendStatus('', 'Command aborted')),
    ),
    ExecutionErrorCode.timeout => StateError(
      _bashFailureWithCapture(
        error,
        _appendStatus(
          _retryNoticePrefix(notices),
          bashTimeoutStatus(
            timeoutArg: timeoutArg,
            errorMessage: error.message,
          ),
        ),
      ),
    ),
    _ => StateError('${_retryNoticePrefix(notices)}$error'),
  };
}

/// Appends the killed call's partial capture (stderr after stdout, each
/// tail-truncated to the tool budget) to a bash failure message.
String _bashFailureWithCapture(ExecutionError error, String message) {
  final parts = <String>[
    if (error.stdout.isNotEmpty)
      '--- partial stdout ---\n${_truncateBashOutput(error.stdout)}',
    if (error.stderr.isNotEmpty)
      '--- partial stderr ---\n${_truncateBashOutput(error.stderr)}',
  ];
  return parts.isEmpty ? message : '$message\n${parts.join('\n')}';
}

/// Joins exec stdout and stderr (stderr after stdout).
String _bashOutput(ShellExecResult execResult) {
  final parts = <String>[
    if (execResult.stdout.isNotEmpty) execResult.stdout,
    if (execResult.stderr.isNotEmpty) execResult.stderr,
  ];
  return parts.join('\n');
}

/// Truncates command output to the tail, annotating what was cut.
String _truncateBashOutput(String output) {
  final truncation = _truncateTail(output);
  if (!truncation.truncated) return output;
  final startLine = truncation.totalLines - truncation.outputLines + 1;
  final endLine = truncation.totalLines;
  var notice =
      '\n\n[Showing lines $startLine-$endLine of ${truncation.totalLines}';
  if (truncation.truncatedBy == _TruncatedBy.bytes) {
    notice += ' (${formatToolSize(defaultToolMaxBytes)} limit)';
  }
  return '${truncation.content}$notice.]';
}

/// Prepends the retry notices (if any) to a tool result so the model sees
/// that earlier attempts hung or timed out before this one succeeded.
String _retryNoticePrefix(List<String> notices) =>
    notices.isEmpty ? '' : '${notices.join('\n')}\n';

/// The yield-aware foreground bash path: the command runs as a registry job
/// from the start; settling before the yield token fires produces the
/// classic inline result, a yield moves it to the background untouched.
Future<ToolExecutionResult> _shellViaJob(
  ExecutionEnv env,
  ShellJobRegistry jobs,
  String command, {
  String? stdinData,
  required Duration? timeout,
  required num? timeoutArg,
  required CancelToken? cancelToken,
  required CancelToken yieldToken,
  PasswordPromptCallback? onPasswordPrompt,
  required Duration passwordQuiet,
  String? rewriteNotice,
}) async {
  // Live stdin + password-ask detection (issue #367): the channel keeps
  // the pipe open so an answer reaches the RUNNING process; the detector
  // watches the live output stream and, on a password ask, calls the host
  // (the masked sheet) and writes the answer through the channel. The
  // password itself never appears in the transcript — only in the sheet.
  final channel = onPasswordPrompt == null ? null : LiveStdinChannel();
  final detector = onPasswordPrompt == null
      ? null
      : PasswordPromptDetector(
          onPrompt: (title) async {
            final answer = await onPasswordPrompt(title);
            channel!.write('${answer ?? ''}\n');
          },
          quiet: passwordQuiet,
        );
  final entry = await jobs.start(
    command,
    options: ShellExecOptions(
      cwd: env.cwd,
      timeout: timeout,
      // gh-1455: no caller cancel token — the job must survive a run
      // abort; the run unwind below hands it to the background instead.
      stdinData: stdinData,
      liveStdin: channel,
    ),
  );
  final outputSub = detector == null
      ? null
      : entry.job.output.listen(detector.feed);
  try {
    return await _awaitJobOutcome(
      env,
      jobs,
      entry,
      yieldToken,
      cancelToken: cancelToken,
      timeoutArg: timeoutArg,
      rewriteNotice: rewriteNotice,
    );
  } finally {
    await outputSub?.cancel();
    detector?.dispose();
  }
}

Future<ToolExecutionResult> _awaitJobOutcome(
  ExecutionEnv env,
  ShellJobRegistry jobs,
  ShellJobEntry entry,
  CancelToken yieldToken, {
  CancelToken? cancelToken,
  required num? timeoutArg,
  String? rewriteNotice,
}) async {
  final finished = await Future.any<bool>([
    entry.settled.then((_) => true),
    yieldToken.onCancel.then((_) => false),
    // gh-1455: the RUN aborting (Agent.abort, the idle watchdog) must not
    // kill the job either — it unwinds this call exactly like a yield,
    // handing the still-running process to the background.
    if (cancelToken != null) cancelToken.onCancel.then((_) => false),
  ]);

  if (!finished) {
    return _backgroundHandbackResult(
      env,
      jobs,
      entry,
      yieldToken,
      cancelToken: cancelToken,
      rewriteNotice: rewriteNotice,
    );
  }
  return _settledInlineResult(
    env,
    entry,
    timeoutArg: timeoutArg,
    rewriteNotice: rewriteNotice,
  );
}

/// gh-1455: the supervisor's cancel_retry cancel (StuckCallFollowUp on the
/// CALL token) is a cancel-and-RETRY, not a background conversion — this
/// predicate tells that case apart from a run abort / steering yield.
bool _isSupervisorAbort(CancelToken? cancelToken, CancelToken yieldToken) =>
    cancelToken != null &&
    cancelToken.isCancelled &&
    cancelToken.cancelReason is StuckCallFollowUp &&
    !yieldToken.isCancelled;

/// The unwound-call branch of [_awaitJobOutcome]: the supervisor's
/// cancel-retry fails the call exactly like the pre-gh-1455 token-kill did
/// (so the supervisor reclassifies the attempt and retries) — but the job
/// itself keeps running (the gh-1455 firewall keeps caller tokens out of
/// job space). Every other unwind hands the still-running job to the
/// background with an honest summary.
Future<ToolExecutionResult> _backgroundHandbackResult(
  ExecutionEnv env,
  ShellJobRegistry jobs,
  ShellJobEntry entry,
  CancelToken yieldToken, {
  CancelToken? cancelToken,
  String? rewriteNotice,
}) async {
  if (_isSupervisorAbort(cancelToken, yieldToken)) {
    final log = await env.readTextFile(entry.logPath);
    var output = log.isErr ? '' : log.valueOrNull!;
    if (output.endsWith('\n')) {
      output = output.substring(0, output.length - 1);
    }
    throw StateError(_appendStatus(output, 'Command aborted'));
  }
  // gh-1455: the supervisor cancels the CALL token (StuckCallFollowUp)
  // while steering cancels the phase yield — a cancel from either means
  // the handback must name its real cause, so check both reasons.
  final supervisorMoved =
      yieldToken.cancelReason is StuckCallFollowUp ||
      (cancelToken?.cancelReason is StuckCallFollowUp);
  final tail = await jobs.tail(entry.id, maxLines: 20);
  final handback = stuckBackgroundHandbackText(
    jobId: entry.id,
    logPath: entry.logPath,
    supervisorMoved: supervisorMoved,
    partialOutput: tail,
  );
  return ToolExecutionResult.text(
    rewriteNotice == null ? handback : '$rewriteNotice\n$handback',
  );
}

/// The settled-inline branch of [_awaitJobOutcome]: report exactly like
/// the synchronous path and suppress the registry's settle notification
/// (the result is already here).
Future<ToolExecutionResult> _settledInlineResult(
  ExecutionEnv env,
  ShellJobEntry entry, {
  required num? timeoutArg,
  String? rewriteNotice,
}) async {
  entry.suppressSettleNotification();
  final log = await env.readTextFile(entry.logPath);
  // The log file is newline-terminated; the inline result is not.
  var rawOutput = log.isErr ? '' : log.valueOrNull!;
  if (rawOutput.endsWith('\n')) {
    rawOutput = rawOutput.substring(0, rawOutput.length - 1);
  }
  // Issue #1408 AC3 (review 5456649624): the notice rides AFTER
  // tail-truncation — _truncateTail keeps the TAIL, so a head-prefixed
  // notice is cut exactly when the output is long enough to truncate,
  // silently defeating the "the agent sees the rewrite" contract.
  final truncation = _truncateTail(rawOutput);
  var output = !truncation.truncated
      ? rawOutput
      : '${truncation.content}\n\n[Showing lines '
            '${truncation.totalLines - truncation.outputLines + 1}-'
            '${truncation.totalLines} of ${truncation.totalLines}.]';
  if (rewriteNotice != null) output = '$rewriteNotice\n$output';
  return _settledOutcome(entry, output, timeoutArg: timeoutArg);
}

/// The settled-job verdict: timeout / cancel / non-zero exit all throw the
/// evidence-carrying StateError the bash contract has always had.
ToolExecutionResult _settledOutcome(
  ShellJobEntry entry,
  String output, {
  required num? timeoutArg,
}) {
  final exitCode = entry.exitCode ?? -1;
  if (entry.stopReason == 'timeout') {
    throw StateError(
      _appendStatus(
        output,
        bashTimeoutStatus(
          timeoutArg: timeoutArg,
          effectiveTimeout: entry.timeout,
        ),
      ),
    );
  }
  if (entry.stopReason == 'cancelled') {
    throw StateError(_appendStatus(output, 'Command aborted'));
  }
  if (exitCode != 0) {
    throw StateError(
      _appendStatus(output, 'Command exited with code $exitCode'),
    );
  }
  return ToolExecutionResult.text(output.isEmpty ? '(no output)' : output);
}

/// Creates the `bash_job` tool: inspect and stop the session's background
/// shell jobs (see [ShellJobRegistry]).
AgentTool bashJobTool(ShellJobRegistry jobs) {
  return AgentTool(
    name: 'bash_job',
    label: 'bash job',
    // `stop` kills a process, so the whole tool sits at the write tier
    // (task_send precedent); status/output are plain reads.
    tier: ApprovalTier.write,
    description:
        'Manage background shell jobs (from bash background: true). '
        'Actions: "status" lists running + last 20 exited (all: true = '
        'every job; id = one), "output" tails a log (id, lines), "stop" '
        'kills a running job (id).',
    parameters: const {
      'type': 'object',
      'properties': {
        'action': {
          'type': 'string',
          'enum': ['status', 'output', 'stop'],
          'description': 'What to do with the job(s)',
        },
        'id': {
          'type': 'string',
          'description': 'The job id (e.g. sh-1); required for output/stop',
        },
        'lines': {
          'type': 'number',
          'description': 'Log tail size for output (default 50)',
        },
        'all': {
          'type': 'boolean',
          'description': 'status without id: list every exited job too',
        },
      },
      'required': ['action'],
    },
    execute: (arguments, cancelToken, onUpdate) async {
      final action = arguments['action'] as String;
      final id = arguments['id'] as String?;
      final lines = (arguments['lines'] as num?)?.toInt();
      final all = arguments['all'] as bool? ?? false;
      return switch (action) {
        'status' => _bashJobStatusResult(jobs, id, all: all),
        'output' => await _bashJobOutputResult(jobs, id, lines),
        'stop' => await _bashJobStopResult(jobs, id),
        _ => throw StateError('unknown bash_job action: $action'),
      };
    },
  );
}

/// How many exited jobs the no-id `status` listing shows beyond the running
/// ones (gh-1438 AC3 — the production storm dumped 1600+ exited rows).
const _statusExitedLimit = 20;

ToolExecutionResult _bashJobStatusResult(
  ShellJobRegistry jobs,
  String? id, {
  required bool all,
}) => id == null
    ? _bashJobStatusListing(jobs, all)
    : _bashJobStatusLookup(jobs, id);

/// The no-id `status` listing: every running job, plus the most recent
/// exited ones up to [_statusExitedLimit] unless [all] — gh-1438 AC3, the
/// production storm dumped 1600+ exited rows.
ToolExecutionResult _bashJobStatusListing(ShellJobRegistry jobs, bool all) {
  final everything = jobs.jobs;
  if (everything.isEmpty) {
    return ToolExecutionResult.text('No background jobs this session.');
  }
  // gh-1459 ask #4: a no-id status sweep is the model looking at every
  // running job — each counts as a probe for the headless drain's
  // liveness leg.
  for (final entry in everything) {
    if (entry.isRunning) entry.markProbed();
  }
  if (all) {
    return ToolExecutionResult.text(
      everything.map(_shellJobStatusLine).join('\n'),
    );
  }
  final running = [
    for (final entry in everything)
      if (entry.isRunning) entry,
  ];
  final exited = [
    for (final entry in everything)
      if (!entry.isRunning) entry,
  ]..sort(_bySettledDescending);
  final shown = exited.take(_statusExitedLimit).toList();
  final lines = [
    ...running.map(_shellJobStatusLine),
    ...shown.map(_shellJobStatusLine),
    if (exited.length > shown.length)
      '… ${exited.length - shown.length} more exited job(s) not shown '
          '(${exited.length} exited total, logs stay in .fah/bash_jobs/) — '
          'pass all: true to list every job.',
  ];
  return ToolExecutionResult.text(lines.join('\n'));
}

/// The with-id `status` result. gh-1459 ask #4: a status probe of a
/// resolved job counts as liveness for the headless drain's liveness leg.
ToolExecutionResult _bashJobStatusLookup(ShellJobRegistry jobs, String id) {
  final lookup = jobs.lookup(id);
  switch (lookup) {
    case ShellJobHit(:final entry):
      entry.markProbed();
    case ShellJobNearMiss(:final entry):
      entry.markProbed();
    case ShellJobPrefixAmbiguous():
    case ShellJobUnknownId():
  }
  return switch (lookup) {
    ShellJobHit(:final entry) => ToolExecutionResult.text(
      _shellJobStatusLine(entry),
    ),
    ShellJobNearMiss(:final entry) => ToolExecutionResult.text(
      '${_staleIdNote(lookup.id, entry.id)}\n'
      '${_shellJobStatusLine(entry)}\n'
      '${_resolvedStateLine(entry)}',
    ),
    ShellJobPrefixAmbiguous(:final entries) => ToolExecutionResult.text(
      _ambiguousText(lookup.id, entries),
    ),
    ShellJobUnknownId(:final closestIds) => ToolExecutionResult.text(
      _unknownIdText(
        jobs,
        lookup.id,
        closestIds,
        gcNote: _statusUnknownText(jobs, lookup.id, closestIds),
      ),
    ),
  };
}

/// The `status` unknown-id flow: malformed ids dead-end with the shortest
/// error (E3), GC'd ids render the honest compacted note, everything else
/// gets the plain closest-ids result (AC2).
String _statusUnknownText(
  ShellJobRegistry jobs,
  String id,
  List<String> closestIds,
) {
  if (parseShellJobIdParts(id) == null) {
    throw StateError('unknown background job: $id');
  }
  return _unknownIdText(jobs, id, closestIds, gcNote: _gcStatusNote(jobs, id));
}

Future<ToolExecutionResult> _bashJobOutputResult(
  ShellJobRegistry jobs,
  String? id,
  int? lines,
) async {
  if (id == null) throw StateError('bash_job output requires an id');
  final maxLines = lines ?? 50;
  final lookup = jobs.lookup(id);
  switch (lookup) {
    case ShellJobHit(:final entry):
      // gh-1459 ask #4: reading the job's log is the model probing it —
      // it counts as liveness for the drain's liveness leg.
      entry.markProbed();
      return ToolExecutionResult.text(
        await _exactOutputText(jobs, entry, maxLines),
      );
    case ShellJobNearMiss(:final entry):
      entry.markProbed();
      final tail = await jobs.tail(entry.id, maxLines: maxLines);
      return ToolExecutionResult.text(
        '${_staleIdNote(lookup.id, entry.id)}\n'
        '${tail.isEmpty ? '(no output yet)' : tail}\n'
        '${_resolvedStateLine(entry)}',
      );
    case ShellJobPrefixAmbiguous(:final entries):
      return ToolExecutionResult.text(_ambiguousText(lookup.id, entries));
    case ShellJobUnknownId(:final closestIds):
      return _unknownOutputResult(jobs, lookup.id, closestIds, maxLines);
  }
}

/// The unknown-id `output` flow: malformed ids dead-end with the shortest
/// error (E3), GC'd ids fall back to the on-disk log while it exists (AC4)
/// or degrade to the clean error once it is gone (E2), and everything else
/// gets the plain closest-ids result (AC2).
Future<ToolExecutionResult> _unknownOutputResult(
  ShellJobRegistry jobs,
  String id,
  List<String> closestIds,
  int maxLines,
) async {
  if (parseShellJobIdParts(id) == null) {
    throw StateError('unknown background job: $id');
  }
  final gcPath = jobs.prunedLogPath(id);
  if (gcPath != null) {
    final tail = await jobs.tailFromLog(gcPath, maxLines: maxLines);
    if (tail == null) throw StateError('unknown background job: $id');
    return ToolExecutionResult.text(
      'Job $id already exited; its log was compacted out of the registry. '
      'Tail from disk:\n'
      '${tail.isEmpty ? '(no output)' : tail}',
    );
  }
  return ToolExecutionResult.text(_unknownIdText(jobs, id, closestIds));
}

Future<ToolExecutionResult> _bashJobStopResult(
  ShellJobRegistry jobs,
  String? id,
) async {
  if (id == null) throw StateError('bash_job stop requires an id');
  final entry = jobs.job(id);
  if (entry != null) {
    if (!entry.isRunning) {
      return ToolExecutionResult.text(
        '$id already finished (exit code ${entry.exitCode})',
      );
    }
    await entry.stop();
    return ToolExecutionResult.text('Stopped $id');
  }
  // gh-1438 AC5: the destructive action NEVER acts on a resolved guess —
  // malformed ids keep the shortest error, GC'd ids are honestly done, and
  // every other unknown id gets the closest-ids hint only.
  if (parseShellJobIdParts(id) == null) {
    throw StateError('unknown background job: $id');
  }
  if (jobs.prunedLogPath(id) != null) {
    return ToolExecutionResult.text(
      'Job $id already exited (its log was compacted out of the registry) — '
      'nothing to stop.',
    );
  }
  final hint = closestShellJobIds(id, [for (final j in jobs.jobs) j.id]);
  final buffer = StringBuffer(
    'Unknown background job: $id — stop requires the exact job id '
    '(it never acts on a resolved guess).',
  );
  if (hint.isEmpty) {
    buffer.write(' No jobs are retained this session.');
  } else {
    buffer.write(' Closest retained job ids:');
    for (final candidate in hint) {
      final entry = jobs.job(candidate);
      buffer.write(
        '\n- ${entry == null ? candidate : _shellJobStatusLine(entry)}',
      );
    }
  }
  return ToolExecutionResult.text(buffer.toString());
}

/// "[Job id X] was not found — resolved to [Y] (same `sh-<n>-` prefix)."
String _staleIdNote(String requested, String resolved) =>
    'Job id $requested was not found — resolved to $resolved '
    '(same sh-<n>- prefix).';

/// The exit-state sentence a resolved near-miss carries after its tail
/// (AC1 for exited, edge case E4 for running).
String _resolvedStateLine(ShellJobEntry entry) {
  if (entry.isRunning) {
    return '${entry.id} is still running — use ${entry.id} for further calls.';
  }
  return '${entry.id} already exited '
      '(exit code ${entry.exitCode}, ${_settledAgo(entry)}) — '
      'stop polling the stale id.';
}

/// The one-line context an exact-id `output` gains once the job exited
/// ("unchanged, plus exited-Nm-ago context").
Future<String> _exactOutputText(
  ShellJobRegistry jobs,
  ShellJobEntry entry,
  int maxLines,
) async {
  final tail = await jobs.tail(entry.id, maxLines: maxLines);
  if (entry.isRunning) return tail.isEmpty ? '(no output yet)' : tail;
  return '${tail.isEmpty ? '(no output)' : tail}\n'
      '${entry.id} already exited '
      '(exit code ${entry.exitCode}, ${_settledAgo(entry)}).';
}

String _settledAgo(ShellJobEntry entry) {
  final settledAt = entry.settledAt;
  if (settledAt == null) return 'just now';
  return shellJobSettledAgo(DateTime.now().difference(settledAt));
}

/// E1: a requested id shares its numeric part with several retained jobs —
/// listed, never silently picked.
String _ambiguousText(String requested, List<ShellJobEntry> entries) {
  final buffer = StringBuffer(
    'Job id $requested matches several jobs (shared sh-<n>- prefix) — '
    'no resolution; use the exact id:',
  );
  for (final entry in entries) {
    buffer.write('\n- ${_shellJobStatusLine(entry)}');
  }
  return buffer.toString();
}

/// AC2: the never-registered wording with the ≤3 closest retained ids.
/// [gcNote] (a GC'd id seen through a read action) replaces the whole text.
String _unknownIdText(
  ShellJobRegistry jobs,
  String id,
  List<String> closestIds, {
  String? gcNote,
}) {
  if (gcNote != null) return gcNote;
  final buffer = StringBuffer(
    'Job id $id was never registered in this session — do not retry it.',
  );
  if (closestIds.isEmpty) {
    buffer.write(' No jobs are retained this session.');
  } else {
    buffer.write(' Closest retained job ids:');
    for (final candidate in closestIds) {
      final entry = jobs.job(candidate);
      buffer.write(
        '\n- ${entry == null ? candidate : _shellJobStatusLine(entry)}',
      );
    }
  }
  return buffer.toString();
}

/// The `status` rendering of a GC'd id (no tail read — AC4 scopes the
/// on-disk fallback to `output`).
String? _gcStatusNote(ShellJobRegistry jobs, String id) {
  final gcPath = jobs.prunedLogPath(id);
  if (gcPath == null) return null;
  return 'Job $id already exited; its log was compacted out of the registry '
      '(log file: $gcPath — read it with bash_job output or the read tool).';
}

/// Exited jobs newest-settled first — the job the agent is most likely
/// polling for leads. Never-settled stragglers sort last.
int _bySettledDescending(ShellJobEntry a, ShellJobEntry b) {
  final epoch = DateTime.fromMillisecondsSinceEpoch(0);
  return (b.settledAt ?? epoch).compareTo(a.settledAt ?? epoch);
}

String _shellJobStatusLine(ShellJobEntry entry) {
  final state = entry.isRunning ? 'running' : 'exited(${entry.exitCode})';
  // gh-1604: first/last ~120 chars of the flattened command — a multi-KB
  // pipeline never renders in full into the wall again.
  final command = shellJobCommandLabel(entry.command);
  // gh-1438: exited rows carry their age — a settled-but-never-collected
  // job is the exact thing stale-id polling hunts for.
  final ago = entry.isRunning ? '' : ' — exited ${_settledAgo(entry)}';
  return '${entry.id}: $state — $command (log: ${entry.logPath})$ago';
}

/// Session-scoped registry of background shell jobs (`bash background: true`
/// and steer-yielded foreground commands).
///
/// A job is a [ShellJob] started through the [BackgroundShell] capability of
/// the environment (local processes only — sandboxed/web environments do not
/// implement it and the tools answer a clean "not supported here" note).
/// stdout/stderr stream into a log file under `.fah/bash_jobs/` so both the
/// model (`bash_job output`, the `read` tool) and the user can inspect it
/// while the job runs. Bench/unattended runs relocate the directory
/// ([jobLogDir], env `FAH_JOB_LOG_DIR`) so the harness's own artifacts never
/// land in the graded task workspace (issue #1408 AC1), and pipe the writes
/// through a redactor ([jobLogRedactor]) so secret values never rest in the
/// logs (issue #1408 AC2).
///
/// When a job settles, [ShellJobRegistry.onSettled] fires — the host's
/// terminal bookkeeping (the job board's Running count, the waiting row)
/// hangs off it. The host turns it into a follow-up/steer message (omp's
/// async-result flow, the same one background `task` jobs use) so the
/// model learns about completions at the next step boundary without
/// polling. A foreground bash call that consumed its job's result inline
/// skips only that model-facing notice
/// ([ShellJobEntry.suppressSettleNotification]) to avoid a duplicate —
/// the bookkeeping itself always runs (issue #562).
library;

import 'dart:async';
import 'dart:math';

import 'package:meta/meta.dart';

import '../env/execution_env.dart';
import '../env/job_log_ceiling.dart';
import '../env/job_log_redaction.dart';
import 'job_id_resolution.dart';
// The boot-sweep process-table probe is VM-only infrastructure (`ps` via
// dart:io); web builds get a stub that always reports "no process table".
import '../env/process_probe_stub.dart'
    if (dart.library.io) '../env/process_probe_io.dart';

final Random _shellJobRandom = Random.secure();

/// The environment variable a bench/unattended run sets to relocate the
/// bash-job log directory OUTSIDE the task workspace (issue #1408 AC1) —
/// the in-container twin of the runner's `$RUNNER_TEMP`. The CLI resolves
/// it at boot (lib/ stays dart:io-free) and hands the value to
/// [ShellJobRegistry.jobLogDir].
const shellJobLogDirEnvVar = 'FAH_JOB_LOG_DIR';

/// The [shellJobLogDirEnvVar] value from [env], trimmed; null when unset or
/// blank. Pure — the executable owns the `Platform.environment` read.
String? jobLogDirOverride(Map<String, String> env) {
  final value = env[shellJobLogDirEnvVar]?.trim();
  return (value == null || value.isEmpty) ? null : value;
}

/// How many leading characters of a job's command the model-facing
/// surfaces keep (gh-1604 item 1): the bench evidence showed multi-KB
/// single-line commands riding every registry card and settle notice.
const shellJobLabelHeadChars = 120;

/// How many trailing characters of a job's command the model-facing
/// surfaces keep (gh-1604 item 1) — the tail names the actual action of a
/// long pipeline (`... ; make test`), which a head-only cut loses.
const shellJobLabelTailChars = 120;

/// The bounded model-facing command label (gh-1604 item 1): whitespace
/// (newlines included) flattened to single spaces, then bounded —
/// single-line commands keep the first [headChars] and last [tailChars]
/// characters joined by a `[…N chars…]` marker that names the TRUE
/// omitted size; multi-line commands keep the HEAD only, no tail.
/// Commands that already fit pass through untouched. Cuts never split a
/// UTF-16 surrogate pair. Pure.
///
/// Why multi-line commands keep only the first line (issue #599 RED
/// contract): the heredoc body is never a transcript row source, and for
/// a multi-line command both the flattened head-crossing and the tail
/// chars are body lines more often than they are the action — echoing
/// them back through every settle notice re-floods the transcript the
/// #599 fix drained. A one-line command's tail is the bench pipeline's
/// action (`… ; make test`), so the single-line class keeps it.
String shellJobCommandLabel(
  String command, {
  int headChars = shellJobLabelHeadChars,
  int tailChars = shellJobLabelTailChars,
}) {
  final flat = command.replaceAll(RegExp(r'\s+'), ' ').trim();
  // Fits: any command whose flattened form fits the head bound passes
  // through untouched — including short multi-line ones (pre-existing
  // flatten-and-show behavior).
  if (flat.length <= headChars) return flat;
  if (!command.trim().contains('\n')) {
    final head = _codepointSafeSlice(flat, 0, headChars);
    final tail = _codepointSafeSlice(
      flat,
      max(0, flat.length - tailChars),
      flat.length,
    );
    final omitted = flat.length - head.length - tail.length;
    if (omitted <= 0) return flat;
    return '$head […$omitted chars…] $tail';
  }
  // Overflows: single-line commands keep head + tail; multi-line
  // commands (issue #599 RED contract) keep the FIRST LINE only,
  // bounded — the first line is the command's face (a heredoc opener,
  // a script's shebang), while everything after it is body more often
  // than it is action. A flattened 120-char head would leak the first
  // body lines; a first-line head cannot. The first line comes from the
  // TRIMMED command: a leading newline must not blank the face
  // (gh-1604 rework).
  final trimmed = command.trim();
  final firstLineEnd = trimmed.indexOf('\n');
  final firstLine =
      (firstLineEnd < 0 ? trimmed : trimmed.substring(0, firstLineEnd))
          .replaceAll(RegExp(r'\s+'), ' ')
          .trim();
  final head = _codepointSafeSlice(firstLine, 0, headChars);
  final omitted = flat.length - head.length;
  return '$head […$omitted chars…]';
}

/// The substring of [text] over `[start, end)`, nudged inward so a cut
/// never separates a surrogate pair (the spill previews' rule).
String _codepointSafeSlice(String text, int start, int end) {
  var s = start.clamp(0, text.length);
  var e = end.clamp(s, text.length);
  if (s > 0 && s < text.length) {
    if (text.codeUnitAt(s) >= 0xDC00 && text.codeUnitAt(s) <= 0xDFFF) s++;
  }
  if (e > s && e < text.length) {
    final unit = text.codeUnitAt(e - 1);
    if (unit >= 0xD800 && unit <= 0xDBFF) e--;
  }
  if (e <= s) return '';
  return text.substring(s, e);
}

/// The model-facing settle notice for [job] — the text the host steers
/// into the conversation (mid-run) or runs as a fresh turn (idle) when a
/// background shell job exits. The command rides the bounded
/// [shellJobCommandLabel], never the full body (gh-1604: a multi-KB
/// command must not enter the transcript through every settle).
String shellJobSettleNoticeText(ShellJobEntry job) {
  return '<system-notice>\n'
      'Background shell job ${job.id} finished with exit code '
      '${job.exitCode}.\n'
      // Issue #599: the preview, never the multi-line body — this
      // notice is echoed into the transcript verbatim, and the full
      // command lives in the job log (right below).
      'Command: ${shellJobCommandLabel(job.command)}\n'
      'Log: ${job.logPath}\n'
      'Check the result with bash_job (action: output) or by reading the '
      'log file, and act on it when the result was awaited.\n'
      '</system-notice>';
}

/// Globally-unique background job id: several fa processes share one
/// workspace, so per-process counters alone (`sh-1`, `sh-2`) would make
/// them append to the SAME `.fah/bash_jobs/<id>.log` and interleave each
/// other's captured output. The microsecond stamp plus a random tail makes
/// cross-process collisions practically impossible.
String newShellJobId(int n) {
  final micros = DateTime.now().microsecondsSinceEpoch.toRadixString(36);
  // dart2js: shifts are 32-bit — `1 << 32` == 0, so nextInt(0) would throw
  // on web and kill every bash call (issue #1074). Spell the bound literally.
  final rand = _shellJobRandom.nextInt(0xFFFFFFFF).toRadixString(36);
  return 'sh-$n-$micros$rand';
}

/// One registered background shell job.
final class ShellJobEntry {
  ShellJobEntry._(this.job, {this.cwd, this.timeout})
    : startedAt = DateTime.now();

  /// The backend handle.
  final ShellJob job;

  /// When the job registered (drives the terminal card's elapsed).
  final DateTime startedAt;

  /// When the registry observed the job's exit (gh-1438) — null while
  /// running. Drives the status line's "exited Nm ago" context and the
  /// retained-entry GC's LRU order. Stamped by the registry's settle
  /// listener; first observation wins.
  DateTime? _settledAt;
  DateTime? get settledAt => _settledAt;

  /// The working directory the job was started from (the dim detail's cwd
  /// tail, issue #429 AC2).
  final String? cwd;

  /// Whether the model-facing settle notice should still be delivered (a
  /// foreground consumer that took the result inline clears it). The
  /// registry's settle bookkeeping runs regardless — see
  /// [ShellJobRegistry.onSettled].
  bool _notifyOnSettle = true;

  /// How often the model probed this job with a read-only `bash_job`
  /// status/output call (gh-1459 ask #4). A generation COUNTER, not a
  /// timestamp — the headless drain's liveness leg compares generations
  /// so the probe clock stays valid under a fake [DateTime] test clock:
  /// a quiet-threshold steer is skipped when the generation advanced
  /// since the last consumed threshold (the model looked itself, so the
  /// notice would be noise).
  int _probeGeneration = 0;

  String get id => job.id;

  /// The command line being executed.
  String get command => job.command;

  /// The log file receiving the job's stdout and stderr.
  String get logPath => job.logPath;

  /// The job's root process id, when the environment exposes one.
  int? get pid => job.pid;

  /// Whether the process is still running.
  bool get isRunning => job.isRunning;

  /// The process exit code, or null while running.
  int? get exitCode => job.exitCode;

  /// Why the job was stopped early ('timeout'/'cancelled'/'stopped'), or
  /// null when it exited on its own.
  String? get stopReason => job.stopReason;

  /// The exec timeout the job was started with (gh-1444 AC5): the honest
  /// "timed out after Ns" text reports THIS cap when the job's own
