      yieldSource.cancel();
      final text = _text(await resultFuture);
      expect(text, contains('a steering message arrived'));
      expect(text, isNot(contains('auto-backgrounded')));
      expect(job.isRunning, isTrue);
      env.jobs.single.complete(0);
    });

