      // UnavailableShell: the classic path surfaces the shell error.
      await expectLater(
        plainTool.execute({'command': 'make'}, null, null),
        throwsA(isA<StateError>()),
      );
      expect(plainRegistry.jobs, isEmpty);
    });
  });

